record Point(int x, int y) {
    Point {
        if (x < 0) x = -x;
        if (y < 0) y = -y;
    }
}
public class Main {
    public static void main(String[] args) {
        var p = new Point(-3, -4);
        System.out.println(p.x() + ":" + p.y());
    }
}

record Score(int value) {
    @Override
    public int value() {
        return value * 2;
    }
}
public class Main {
    public static void main(String[] args) {
        Score s = new Score(7);
        System.out.println(s.value());
    }
}

